@extends('scheduling.public.layout') @section('title',$eventType->name.' — Agenda IRCENTER')
@section('content')<section class="booking-shell"><aside class="booking-service"><span class="eyebrow">Agendamento</span><h1>{{ $eventType->name }}</h1><p>{{ $eventType->description }}</p><dl><div><dt>Duração</dt><dd>{{ $eventType->duration_minutes }} min</dd></div><div><dt>Local</dt><dd>{{ $eventType->location_value ?: ucfirst($eventType->location_type) }}</dd></div></dl></aside><div class="booking-flow"><h2>Escolha data e horário</h2><div class="booking-grid"><div><label for="booking-date">Data</label><input id="booking-date" type="date" min="{{ now($timezone)->format('Y-m-d') }}" max="{{ now($timezone)->addDays($eventType->maximum_days_ahead)->format('Y-m-d') }}"><label for="booking-timezone">Timezone</label><select id="booking-timezone"><option selected>{{ $timezone }}</option><option>UTC</option><option>America/New_York</option></select></div><div><h3 id="slots-title">Horários disponíveis</h3><div id="booking-slots" class="booking-slots" aria-live="polite"><p class="empty-state">Selecione uma data.</p></div></div></div><form method="post" action="{{ route('scheduling.public.store',$eventType) }}" id="booking-form" hidden>@csrf<input type="hidden" name="start" id="selected-start"><input type="hidden" name="timezone" id="selected-timezone" value="{{ $timezone }}"><input type="hidden" name="form_started_at" value="{{ time() }}"><div class="honeypot" aria-hidden="true"><label>Website<input name="website" tabindex="-1" autocomplete="off"></label></div><h2>Seus dados</h2><label>Nome<input name="guest_name" required maxlength="120" value="{{ old('guest_name') }}"></label><label>E-mail<input type="email" name="guest_email" required maxlength="255" value="{{ old('guest_email') }}"></label><div class="form-pair"><label>Telefone (opcional)<input name="guest_phone" maxlength="40"></label><label>Empresa (opcional)<input name="guest_company" maxlength="120"></label></div><label>Observações (opcional)<textarea name="notes" maxlength="2000"></textarea></label>@if($errors->any())<div class="alert alert-danger" role="alert"><ul>@foreach($errors->all() as $error)<li>{{ $error }}</li>@endforeach</ul></div>@endif<button class="button button-primary" type="submit">Confirmar agendamento</button></form></div></section>@endsection
@push('scripts')<script nonce="{{ request()->attributes->get('csp_nonce') }}">(()=>{const date=document.querySelector('#booking-date'),zone=document.querySelector('#booking-timezone'),slots=document.querySelector('#booking-slots'),form=document.querySelector('#booking-form'),start=document.querySelector('#selected-start'),selectedZone=document.querySelector('#selected-timezone');async function load(){if(!date.value)return;slots.innerHTML='<p>Carregando…</p>';try{const url=new URL(@json(route('scheduling.public.availability',$eventType)),location.origin);url.searchParams.set('date',date.value);url.searchParams.set('timezone',zone.value);const response=await fetch(url,{headers:{Accept:'application/json'}});if(!response.ok)throw new Error();const data=await response.json();slots.innerHTML=data.slots.length?'':'<p class="empty-state">Nenhum horário disponível.</p>';data.slots.forEach(slot=>{const button=document.createElement('button');button.type='button';button.className='slot-button';button.textContent=slot.label;button.setAttribute('aria-label','Selecionar '+slot.label);button.onclick=()=>{document.querySelectorAll('.slot-button').forEach(b=>b.classList.remove('is-selected'));button.classList.add('is-selected');start.value=slot.start;selectedZone.value=zone.value;form.hidden=false;form.scrollIntoView({behavior:'smooth',block:'start'});};slots.append(button);});}catch(e){slots.innerHTML='<p class="alert alert-danger">Não foi possível carregar os horários.</p>';}}date.addEventListener('change',load);zone.addEventListener('change',load);})();</script>@endpush
